import json,re
from pathlib import Path
cf=json.loads(Path('/root/DATA/products/CoachForce.json').read_text())
patterns=[re.compile(r'market research',re.I), re.compile(r'cofoaix_market_research_report',re.I)]
for m in cf['meeting_transcripts']:
    txt = m.get('transcript') or m.get('content') or ''
    if any(p.search(txt) for p in patterns):
        print('MATCH meeting',m.get('id'),'date',m.get('date'))
        # print around first match
        for p in patterns:
            mo=p.search(txt)
            if mo:
                start=max(0,mo.start()-120)
                end=min(len(txt),mo.end()+200)
                snippet=txt[start:end]
                print(' snippet:',snippet.replace('\n',' ')[:400])
                break
        print('---')
PY", "security_risk": "LOW", "summary": "Search CoachForce meeting transcripts for market research mentions"}

{"command": "python3 - <<'PY'
import json,re
from pathlib import Path
pf=json.loads(Path('/root/DATA/products/PersonalizeForce.json').read_text())
patterns=[re.compile(r'competitor',re.I), re.compile(r'strength',re.I), re.compile(r'weakness',re.I), re.compile(r'adobe|ibm|salesforce|dynamic yield|optimizely',re.I)]
for m in pf['meeting_transcripts']:
    txt=m.get('transcript') or m.get('content') or ''
    if any(p.search(txt) for p in patterns):
        # require competitor plus (strength or weakness)
        if re.search(r'competitor',txt,re.I) and (re.search(r'strength',txt,re.I) or re.search(r'weakness',txt,re.I)):
            print('MATCH meeting',m['id'],'date',m.get('date'))
            # show snippet around 'strength'
            for kw in ['strength','weakness','competitor']:
                mo=re.search(kw,txt,re.I)
                if mo:
                    print(' snippet:',txt[max(0,mo.start()-120):mo.start()+250].replace('\n',' ')[:450])
                    break
            print('participants',m.get('participants'))
            print('---')
PY", "security_risk": "LOW", "summary": "Search PersonalizeForce meeting transcripts for strengths/weaknesses competitor discussions"}

