import json,re
from pathlib import Path
cf=json.loads(Path('/root/DATA/products/CoachForce.json').read_text())
patterns=[re.compile(r'market research',re.I), re.compile(r'cofoaix_market_research_report',re.I)]
for m in cf['meeting_transcripts']:
    txt = m.get('transcript') or m.get('content') or ''
    if any(p.search(txt) for p in patterns):
        print('MATCH meeting',m.get('id'),'date',m.get('date'))
        # print around first match
        for p in patterns:
            mo=p.search(txt)
            if mo:
                start=max(0,mo.start()-120)
                end=min(len(txt),mo.end()+200)
                snippet=txt[start:end]
                print(' snippet:',snippet.replace('\n',' ')[:400])
                break
        print('---')
PY", "security_risk": "LOW", "summary": "Search CoachForce meeting transcripts for market research mentions"}

